<?php $title='Messages';require 'includes/header.php';$rows=$pdo->query("SELECT * FROM contact_messages ORDER BY id DESC")->fetchAll();?><h1>Messages</h1><div class="table-responsive bg-white rounded-4 shadow-sm"><table class="table"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th>Subject</th><th>Message</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['subject'])?></td><td><?=e($r['message'])?></td></tr><?php endforeach;?></tbody></table></div><?php require 'includes/footer.php';?>